function wsum(w,pr){const n={Present:0,'Half Day':0,'Paid Leave':0,Absent:0,'Weekly Off':0,Holiday:0};let ot=0;for(let d=new Date(pr[0]);d<=pr[1];d.setDate(d.getDate()+1)){const r=recOf(w,ld(d));if(r){if(n[r.status]!=null)n[r.status]++;if(r.status!='Absent')ot+=+r.ot_hours||0}}
const c=(l,v,col)=>`<div style="flex:1 1 110px;min-width:105px;border:1px solid var(--line,#E5E7EB);border-left:4px solid ${col};border-radius:12px;padding:8px 12px;background:#fff"><b style="font-size:20px">${v}</b><br><small style="color:var(--mut)">${l}</small></div>`;
return `<div style="display:flex;flex-wrap:wrap;gap:8px;margin:0 0 14px">${c('Present days',n.Present,'#16A34A')}${c('Half days',n['Half Day'],'#F59E0B')}${c('Paid leave',n['Paid Leave'],'#2563EB')}${c('Absent',n.Absent,'#DC2626')}${c('Weekly off',n['Weekly Off'],'#6B7280')}${c('Holiday',n.Holiday,'#7C3AED')}${c('Total OT hours',Math.round(ot*100)/100,'#0F766E')}</div>`}
const cvKey=()=>{const pr=cvPer();return ld(pr[0])+'|'+ld(pr[1])+'|'+(S.cw||'')};
async function ensureCV(){if(!S.cv)return;const pr=cvPer(),q1=ld(pr[0]),q2=ld(pr[1]),k=cvKey(),wk=S.cw&&W.find(x=>x.id==S.cw);if(CVC[k])return;try{const rows=await getAll('/rest/v1/attendance?select=worker_id,day,status,ot_hours&order=day,worker_id&'+(wk?'worker_id=eq.'+wk.uuid+'&':'')+'day=gte.'+q1+'&day=lte.'+q2),dc={},rm={};rows.forEach(r=>{rm[r.worker_id+'|'+r.day]=r});Object.keys(SAVED).forEach(kk=>{const r=SAVED[kk];if(r.day>=q1&&r.day<=q2&&(!wk||r.worker_id==wk.uuid))rm[kk]=r});Object.values(rm).forEach(r=>{const c=dc[r.day]||(dc[r.day]={});c[r.status]=(c[r.status]||0)+1});CVC[k]={dc,rm}}catch(e){S.cv=0;toast(e.message,1)}}
async function markDayRec(w,day,status,ot){const r=await api('/rest/v1/attendance?on_conflict=worker_id,day','POST',{worker_id:w.uuid,day,status,ot_hours:(status!='Absent'&&+ot>0)?+ot:0},'resolution=merge-duplicates,return=representation');const row=r[0];SAVED[row.worker_id+'|'+row.day]=row;if(day>=S.p1&&day<=S.p2){const i=ATT.findIndex(x=>x.worker_id==row.worker_id&&x.day==row.day);if(i<0)ATT.push(row);else ATT[i]=row}}
