async function saveDayPay(code,val){const w=W.find(x=>x.id==code),row=w&&BYDAY[w.uuid+'|'+S.date];if(!row)throw new Error('Mark attendance first');const v=String(val).trim(),n=v===''?null:Math.max(0,+v);if(n!==null&&isNaN(n))throw new Error('Enter a valid amount');const r=await patchRow('attendance',row.id,{day_pay:n});ATT[ATT.findIndex(x=>x.id==row.id)]=r;build();R();toast(n===null?'Back to automatic pay':'Day pay saved')}
